mapper.select:
SELECT COALESCE(MAX(revision), 0) + 1
  FROM media_plans
 WHERE chapter_id = #{chapterId}

mapper.insert:
INSERT INTO media_plans (
  id, chapter_id, chapter_row_version, source_hash, production_mode, revision,
  narration_characters, image_generate_count, image_edit_count, basic_motion_seconds,
  planned_i2v_seconds, estimated_cost, created_at
) VALUES (
  #{id,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler},
  #{chapterId}, #{chapterRowVersion}, #{sourceHash}, #{productionMode}, #{revision},
  #{narrationCharacters}, #{imageGenerateCount}, #{imageEditCount}, #{basicMotionSeconds},
  #{plannedI2vSeconds}, #{estimatedCost}, #{createdAt}
)

INSERT INTO media_scene_plans (
  media_plan_id, scene_index, scene_id, scene_order_index, narration, duration_seconds
) VALUES (
  #{mediaPlanId,typeHandler=com.narrativex.backend.feature.generation.infrastructure.persistence.mybatis.UuidTypeHandler},
  #{sceneIndex}, #{sceneId}, #{sceneOrderIndex}, #{narration}, #{durationSeconds}
)

INSERT INTO media_beat_plans (
